-- Legacy NOMIS compatibility table
-- This is an unmaintained copy of the NOMIS ORDER_TYPES table, retained to support
-- downstream consumers that depend on the legacy NOMIS data.
-- It is not part of the R&S domain model and deliberately has no relationships to other R&S tables.
-- New functionality should not depend on this table.

CREATE TABLE legacy_order_types (
                                    order_type varchar PRIMARY KEY,
                                    description varchar,
                                    youth_order_flag varchar,
                                    custody_flag varchar,
                                    time_sensitive_flag varchar,
                                    active_flag varchar,
                                    list_seq integer,
                                    update_allowed_flag varchar,
                                    expiry_date date,
                                    create_user_id varchar,
                                    schedule_flag varchar,
                                    charges_flag varchar,
                                    severity_rank integer,
                                    caseload_type varchar,
                                    no_of_hold_days integer,
                                    create_datetime timestamp,
                                    modify_datetime timestamp,
                                    modify_user_id varchar,
                                    audit_timestamp timestamp,
                                    audit_user_id varchar,
                                    audit_module_name varchar,
                                    audit_client_user_id varchar,
                                    audit_client_ip_address varchar,
                                    audit_client_workstation_name varchar,
                                    audit_additional_info varchar,
                                    order_category varchar,
                                    custody_days integer
);

